'use client';

import { useSearchParams, useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import dynamic from 'next/dynamic';

// Dynamically import the MindMap component with no SSR
const MindMap = dynamic(() => import('@/components/MindMap'), { ssr: false });

export default function MindMapPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [mindMapData, setMindMapData] = useState(null);
  const [prdContent, setPrdContent] = useState('');

  useEffect(() => {
    const prd = searchParams.get('prd');
    const data = searchParams.get('data');
    
    if (prd && data) {
      setPrdContent(decodeURIComponent(prd));
      try {
        setMindMapData(JSON.parse(decodeURIComponent(data)));
      } catch (error) {
        console.error('Error parsing mind map data:', error);
      }
    }
  }, [searchParams]);

  if (!mindMapData) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <h2 className="text-2xl font-semibold mb-4">Loading...</h2>
          <p>Please wait while we generate your test cases.</p>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div style={{ padding:'24px 24px 0px 24px', cursor: 'pointer' }}>
        <button 
          onClick={() => router.back()}
          className="mb-4 flex items-center text-gray-600 hover:text-gray-900 transition-colors"
          aria-label="Go back"
        >
          <span className="text-sm mr-1">←</span>
          <span>Back</span>
        </button>
      </div>
      <div style={{ height: 'calc(100vh - 120px)', padding: '24px' }}>
        <MindMap data={mindMapData} prdContent={prdContent} />
      </div>
    </div>
  );
}
